# 組み込みモジュール http による HTTP サーバー

`http` モジュールは Node.js の標準ライブラリに含まれており、インストールは不要です。

```javascript
const http = require('http');

const server = http.createServer((req, res) => {
  if (req.method === 'GET' && req.url === '/info') {
    res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
    res.end(JSON.stringify({ status: 'ok' }));
    return;
  }
  res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
  res.end('Not Found');
});

server.listen(3000, '127.0.0.1', () => {
  console.log('サーバー起動: http://127.0.0.1:3000');
});
```

要点：`createServer` はハンドラー `(req, res)` を受け取る。`req.method` と `req.url` でルートを判定。`res.writeHead(コード, ヘッダー)` でステータスを設定し、`res.end(本文)` で応答を終える。`res.end()` がないとリクエストは止まったままになります。

Keywords: http server, create server, listen port, request response, javascript, node.js, js.

# HTTP-сервер на встроенном модуле http

Модуль `http` входит в стандартную библиотеку Node.js, устанавливать ничего не нужно.

```javascript
const http = require('http');

const server = http.createServer((req, res) => {
  if (req.method === 'GET' && req.url === '/info') {
    res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
    res.end(JSON.stringify({ status: 'ok' }));
    return;
  }
  res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
  res.end('Not Found');
});

server.listen(3000, '127.0.0.1', () => {
  console.log('Сервер слушает http://127.0.0.1:3000');
});
```

Ключевые моменты: `createServer` принимает обработчик `(req, res)`; `req.method` и `req.url` определяют маршрут; `res.writeHead(код, заголовки)` задаёт статус; `res.end(тело)` завершает ответ. Без `res.end()` запрос повиснет.

Keywords: http server, create server, listen port, request response, javascript, node.js, js.

# OS 情報を返す /info エンドポイント付き HTTP サーバー — その2

```javascript
const http = require('http');
const os = require('os');

const HOST = '127.0.0.1';
const PORT = 3000;

function getSystemInfo() {
  const cpus = os.cpus();
  return {
    platform: os.platform(),
    release: os.release(),
    arch: os.arch(),
    hostname: os.hostname(),
    nodeVersion: process.version,
    cpuModel: cpus.length ? cpus[0].model : 'unknown',
    cpuCount: cpus.length,
    totalMemoryMb: Math.round(os.totalmem() / 1024 / 1024),
    freeMemoryMb: Math.round(os.freemem() / 1024 / 1024),
    uptimeSeconds: Math.round(os.uptime())
  };
}

const server = http.createServer((req, res) => {
  if (req.method === 'GET' && req.url === '/info') {
    res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
    res.end(JSON.stringify(getSystemInfo(), null, 2));
    return;
  }

  res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
```

