# フレームワークなしで複数のエンドポイントをルーティング

```javascript
const routes = {
  'GET /info': (req, res) => sendJson(res, 200, getSystemInfo()),
  'GET /health': (req, res) => sendJson(res, 200, { status: 'ok' })
};

function sendJson(res, code, data) {
  res.writeHead(code, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(data));
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const handler = routes[`${req.method} ${url.pathname}`];
  if (handler) {
    handler(req, res);
  } else {
    sendJson(res, 404, { error: 'Not Found' });
  }
});
```

`new URL(req.url, base)` でパスとクエリパラメータを分けられます：`url.pathname` は `/info`、`url.searchParams.get('key')` はパラメータの値です。

Keywords: routing, routes, url path, query params, javascript, node.js, js.

# Роутинг нескольких эндпоинтов без фреймворка

```javascript
const routes = {
  'GET /info': (req, res) => sendJson(res, 200, getSystemInfo()),
  'GET /health': (req, res) => sendJson(res, 200, { status: 'ok' })
};

function sendJson(res, code, data) {
  res.writeHead(code, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(data));
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const handler = routes[`${req.method} ${url.pathname}`];
  if (handler) {
    handler(req, res);
  } else {
    sendJson(res, 404, { error: 'Not Found' });
  }
});
```

`new URL(req.url, base)` отделяет путь от query-параметров: `url.pathname` даст `/info`, а `url.searchParams.get('key')` — значение параметра.

Keywords: routing, routes, url path, query params, javascript, node.js, js.

# POST リクエストの本文を読む

本文はストリームで届くので、手動で組み立てる必要があります。

```javascript
function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    req.on('data', (chunk) => chunks.push(chunk));
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

const server = http.createServer(async (req, res) => {
  if (req.method === 'POST' && req.url === '/echo') {
    const raw = await readBody(req);
    const data = JSON.parse(raw);
    sendJson(res, 200, data);
  }
});
```

Keywords: read request body, post body, parse json body, javascript, node.js, js.

# Чтение тела POST-запроса

Тело приходит потоком, его нужно собрать вручную.

```javascript
function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    req.on('data', (chunk) => chunks.push(chunk));
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

const server = http.createServer(async (req, res) => {
  if (req.method === 'POST' && req.url === '/echo') {
    const raw = await readBody(req);
    const data = JSON.parse(raw);
    sendJson(res, 200, data);
  }
});
```

Keywords: read request body, post body, parse json body, javascript, node.js, js.

# Express による HTTP サーバー

Express は外部の依存パッケージで、`npm install express` で入れます。

```javascript
const express = require('express');
const os = require('os');

const app = express();
app.use(express.json());

app.get('/info', (req, res) => {
  res.json({
    platform: os.platform(),
    arch: os.arch(),
    cpuCount: os.cpus().length,
    totalMemoryMb: Math.round(os.totalmem() / 1024 / 1024)
  });
});

app.listen(3000, () => console.log('Express がポート 3000 で待機中'));
```

Express はルーティングや JSON 本文の解析を自動で行いますが、シンプルなサービスなら組み込みの `http` モジュールで十分です。

Keywords: express, express server, middleware, javascript, node.js, js.

# HTTP-сервер на Express

Express — внешняя зависимость, ставится через `npm install express`.

```javascript
const express = require('express');
const os = require('os');

const app = express();
app.use(express.json());

app.get('/info', (req, res) => {
  res.json({
    platform: os.platform(),
    arch: os.arch(),
    cpuCount: os.cpus().length,
    totalMemoryMb: Math.round(os.totalmem() / 1024 / 1024)
  });
});

app.listen(3000, () => console.log('Express слушает порт 3000'));
```

Express сам разбирает маршруты и JSON-тело, но для простого сервиса встроенного модуля `http` достаточно.

Keywords: express, express server, middleware, javascript, node.js, js.

# 外部への HTTP リクエスト：fetch

Node.js 18 以降は、ライブラリなしでグローバルな `fetch` が使えます。

```javascript
async function loadData(url) {
  const response = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ query: 'test' })
  });

  if (!response.ok) {
    throw new Error(`HTTP ${response.status}`);
  }
  return response.json();
}
```

注意：`fetch` は 4xx や 5xx のコードでは例外を投げません。`response.ok` は自分で確認する必要があります。

Keywords: fetch, http request, api call, get post, javascript, node.js, js.

# Исходящие HTTP-запросы: fetch

Начиная с Node.js 18 глобальный `fetch` доступен без установки библиотек.

```javascript
async function loadData(url) {
  const response = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ query: 'test' })
  });

  if (!response.ok) {
    throw new Error(`HTTP ${response.status}`);
  }
  return response.json();
}
```

Важно: `fetch` не бросает исключение на коды 4xx и 5xx — проверять `response.ok` нужно самостоятельно.

Keywords: fetch, http request, api call, get post, javascript, node.js, js.

# ストリーミング応答の読み取り（SSE とストリーミング）

```javascript
const response = await fetch(url, { method: 'POST', body: JSON.stringify(payload) });
const reader = response.body.getReader();
const decoder = new TextDecoder();
let buffer = '';

while (true) {
  const { done, value } = await reader.read();
  if (done) break;
  buffer += decoder.decode(value, { stream: true });

  const parts = buffer.split('\n\n');
  buffer = parts.pop();
  for (const part of parts) {
    if (part.startsWith('data: ')) {
      const payload = JSON.parse(part.slice(6));
      process.stdout.write(payload.text || '');
    }
  }
}
```

最後の不完全な断片はバッファに残します。そうしないと、パケットの境界で切れた JSON を解析できません。

Keywords: stream, streaming, sse, server sent events, reader, javascript, node.js, js.

# Чтение потокового ответа (SSE и стриминг)

```javascript
const response = await fetch(url, { method: 'POST', body: JSON.stringify(payload) });
const reader = response.body.getReader();
const decoder = new TextDecoder();
let buffer = '';

while (true) {
  const { done, value } = await reader.read();
  if (done) break;
  buffer += decoder.decode(value, { stream: true });

  const parts = buffer.split('\n\n');
  buffer = parts.pop();
  for (const part of parts) {
    if (part.startsWith('data: ')) {
      const payload = JSON.parse(part.slice(6));
      process.stdout.write(payload.text || '');
    }
  }
}
```

Последний неполный фрагмент оставляют в буфере — иначе разорванный по границе пакета JSON не распарсится.

Keywords: stream, streaming, sse, server sent events, reader, javascript, node.js, js.

# ファイル操作

```javascript
const fs = require('fs');
const fsp = require('fs/promises');

const text = fs.readFileSync('config.json', 'utf8');
const data = JSON.parse(text);

async function save(path, obj) {
  await fsp.writeFile(path, JSON.stringify(obj, null, 2), 'utf8');
}
```

同期関数（`readFileSync`）はイベントループをブロックします。リクエストのハンドラー内では `fs/promises` の非同期版を使います。

Keywords: file, read file, write file, fs module, javascript, node.js, js.

# Работа с файлами

```javascript
const fs = require('fs');
const fsp = require('fs/promises');

const text = fs.readFileSync('config.json', 'utf8');
const data = JSON.parse(text);

async function save(path, obj) {
  await fsp.writeFile(path, JSON.stringify(obj, null, 2), 'utf8');
}
```

Синхронные функции (`readFileSync`) блокируют цикл событий — в обработчиках запросов используют асинхронные версии из `fs/promises`.

Keywords: file, read file, write file, fs module, javascript, node.js, js.

# 非同期処理：Promise と async/await

```javascript
async function main() {
  try {
    const [users, posts] = await Promise.all([
      fetch('/api/users').then((r) => r.json()),
      fetch('/api/posts').then((r) => r.json())
    ]);
    console.log(users.length, posts.length);
  } catch (error) {
    console.error('エラー:', error.message);
  }
}
```

`Promise.all` はリクエストを並列に実行し、1つでも失敗すると全体が失敗します。`Promise.allSettled` は、拒否されたものも含めてすべての結果を返します。

Keywords: async, await, promise, promises, asynchronous, javascript, node.js, js.

# Асинхронность: промисы и async/await

```javascript
async function main() {
  try {
    const [users, posts] = await Promise.all([
      fetch('/api/users').then((r) => r.json()),
      fetch('/api/posts').then((r) => r.json())
    ]);
    console.log(users.length, posts.length);
  } catch (error) {
    console.error('Ошибка:', error.message);
  }
}
```

`Promise.all` выполняет запросы параллельно и падает, если упал хотя бы один. `Promise.allSettled` возвращает результаты всех, включая отклонённые.

Keywords: async, await, promise, promises, asynchronous, javascript, node.js, js.

# コマンドライン引数と環境変数

```javascript
const args = process.argv.slice(2);
const command = args[0];

const port = process.env.PORT || 3000;
const apiKey = process.env.API_KEY;

if (!apiKey) {
  console.error('環境変数 API_KEY が設定されていません');
  process.exit(1);
}
```

`process.argv[0]` は Node.js のパス、`process.argv[1]` はスクリプトのパスなので、ユーザーの引数はインデックス 2 から始まります。

Keywords: argv, command line arguments, env, environment variables, javascript, node.js, js.

# Аргументы командной строки и переменные окружения

```javascript
const args = process.argv.slice(2);
const command = args[0];

const port = process.env.PORT || 3000;
const apiKey = process.env.API_KEY;

if (!apiKey) {
  console.error('Не задана переменная окружения API_KEY');
  process.exit(1);
}
```

`process.argv[0]` — путь к Node.js, `process.argv[1]` — путь к скрипту, поэтому пользовательские аргументы начинаются с индекса 2.

Keywords: argv, command line arguments, env, environment variables, javascript, node.js, js.

# モジュール：CommonJS と ESM

CommonJS（package.json に `"type": "module"` がない場合の `.js` の既定）：

```javascript
const http = require('http');
module.exports = { getSystemInfo };
```

ESM（package.json に `"type": "module"` がある場合、または `.mjs` ファイル）：

```javascript
import http from 'node:http';
export { getSystemInfo };
```

1つのファイルで両方を混ぜることはできません。`node:` 接頭辞は組み込みモジュールであることを明示し、同名のパッケージによるすり替えを防ぎます。

Keywords: module, require, import, export, commonjs, esm, javascript, node.js, js.

# Модули: CommonJS и ESM

CommonJS (по умолчанию в `.js`, если в package.json нет `"type": "module"`):

```javascript
const http = require('http');
module.exports = { getSystemInfo };
```

ESM (при `"type": "module"` в package.json или в файлах `.mjs`):

```javascript
import http from 'node:http';
export { getSystemInfo };
```

Смешивать их в одном файле нельзя. Префикс `node:` явно указывает на встроенный модуль и защищает от подмены пакетом с тем же именем.

Keywords: module, require, import, export, commonjs, esm, javascript, node.js, js.

# プロセスの正しい終了

```javascript
const server = http.createServer(handler);
server.listen(3000);

process.on('SIGINT', () => {
  console.log('停止しています...');
  server.close(() => process.exit(0));
});
```

`server.close()` は新しい接続の受け付けをやめ、処理中の接続が終わるのを待ちます。

Keywords: graceful shutdown, sigint, close server, javascript, node.js, js.

# Корректное завершение процесса

```javascript
const server = http.createServer(handler);
server.listen(3000);

process.on('SIGINT', () => {
  console.log('Останавливаюсь...');
  server.close(() => process.exit(0));
});
```

`server.close()` перестаёт принимать новые соединения и ждёт завершения текущих.

Keywords: graceful shutdown, sigint, close server, javascript, node.js, js.

# JavaScript の配列メソッド

```javascript
const users = [
  { name: 'Aiko', age: 28, active: true },
  { name: 'Kenji', age: 35, active: false },
  { name: 'Yui', age: 22, active: true }
];

const active = users.filter((u) => u.active);
const names = users.map((u) => u.name);
const totalAge = users.reduce((sum, u) => sum + u.age, 0);
const found = users.find((u) => u.age > 30);
const hasYoung = users.some((u) => u.age < 25);
const allAdults = users.every((u) => u.age >= 18);
const sorted = [...users].sort((a, b) => a.age - b.age);
```

`sort` は元の配列を変更するので、スプレッド構文でコピーしてから使います。比較関数なしの `sort` は文字列として並べるため、`[10, 9, 1].sort()` は `[1, 10, 9]` になります。

Keywords: array methods, map, filter, reduce, find, sort, some, every, javascript, node.js, js.

# Методы массивов в JavaScript

```javascript
const users = [
  { name: 'Аня', age: 28, active: true },
  { name: 'Борис', age: 35, active: false },
  { name: 'Вера', age: 22, active: true }
];

const active = users.filter((u) => u.active);
const names = users.map((u) => u.name);
const totalAge = users.reduce((sum, u) => sum + u.age, 0);
const found = users.find((u) => u.age > 30);
const hasYoung = users.some((u) => u.age < 25);
const allAdults = users.every((u) => u.age >= 18);
const sorted = [...users].sort((a, b) => a.age - b.age);
```

`sort` меняет исходный массив, поэтому его копируют через spread. `sort` без функции сравнения сортирует как строки: `[10, 9, 1].sort()` даст `[1, 10, 9]`.

Keywords: array methods, map, filter, reduce, find, sort, some, every, javascript, node.js, js.

# オブジェクトと分割代入

```javascript
const config = { host: '127.0.0.1', port: 3000, debug: false };

const { host, port, timeout = 5000 } = config;
const { debug: isDebug } = config;

const merged = { ...config, port: 8080 };
const { port: _removed, ...withoutPort } = config;

const keys = Object.keys(config);
const entries = Object.entries(config);
const restored = Object.fromEntries(entries);
```

既定値（`timeout = 5000`）はプロパティが `undefined` のときだけ使われ、`null` や `0` のときは使われません。

Keywords: object, destructuring, spread, keys, entries, javascript, node.js, js.

# Объекты и деструктуризация

```javascript
const config = { host: '127.0.0.1', port: 3000, debug: false };

const { host, port, timeout = 5000 } = config;
const { debug: isDebug } = config;

const merged = { ...config, port: 8080 };
const { port: _removed, ...withoutPort } = config;

const keys = Object.keys(config);
const entries = Object.entries(config);
const restored = Object.fromEntries(entries);
```

Значение по умолчанию (`timeout = 5000`) применяется только если свойство равно `undefined`, но не если оно `null` или `0`.

Keywords: object, destructuring, spread, keys, entries, javascript, node.js, js.

# 文字列とテンプレートリテラル

```javascript
const name = '世界';
const greeting = `こんにちは、${name}！`;
const multiline = `1行目
2行目`;

'abc'.padStart(5, '0');
'  テキスト  '.trim();
'a,b,c'.split(',');
['a', 'b'].join('-');
'HELLO'.toLowerCase();
'text'.replaceAll('t', 'T');
'abcdef'.slice(1, 3);
'abc'.includes('b');
```

`replaceAll` は Node.js 15 以降が必要です。それより古い版では、正規表現と `g` フラグを付けた `replace` を使います。

