async function retry(fn, attempts = 3, delayMs = 500) {
  for (let i = 0; i < attempts; i += 1) {
    try {
      return await fn();
    } catch (error) {
      if (i === attempts - 1) throw error;
      await sleep(delayMs * (i + 1));
    }
  }
}
